pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 cashAmt, address actor) public {
        // Restrict to admissible domain: actor must not be the C contract itself or the test contract
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        // Keep deposit reasonable: up to a large amount but avoid overflow
        depositAmt = bound(depositAmt, 0, 1000 ether);
        cashAmt = bound(cashAmt, 0, 1000 ether);

        // Fund actor and perform deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Record total balances after deposit
        uint256 totalAfterDeposit = c.balances(actor);

        // Now attempt a cashout
        if (cashAmt > totalAfterDeposit) {
            cashAmt = totalAfterDeposit; // ensure cashout does not exceed balance
        }
        vm.prank(actor);
        try c.CashOut(cashAmt) {} catch {}

        // After cashout, the balance should equal totalAfterDeposit - cashAmt (invariant: balances only change via successful operations)
        // The reference always satisfies this. The buggy contract may have totalAfterDeposit=0 when depositAmt == 1 ether (MinDeposit),
        // yet cashAmt=0 still passes, but more interestingly, if depositAmt > 1 ether the bug still behaves correctly.
        // Actually the difference appears when depositAmt == 1 ether (exactly MinDeposit) because the bug rejects it,
        // so totalAfterDeposit == 0, then cashAmt==0 leaves balance 0; fine.
        // But the invariant we state is: after a deposit and then a cashout of at most the balance,
        // the final balance must be >= initial balance minus cashout. In the bug when deposit == MinDeposit,
        // deposit is ignored, so initial balance 0 becomes 0, cashout 0 leaves 0. No difference.
        // Let's think differently: we need a scenario where an ignored deposit leads to a later cashout
        // using previously existing balance, and the ignored deposit causes a different state.

        // Better: let the fuzzer choose two actors, an initial deposit by actor1, then actor2 tries a deposit exactly
        // MinDeposit, then actor1 cashes out. In correct contract, actor2's balance increases and total balances sum
        // changes accordingly. In bug, actor2's deposit ignored, so actor1's cashout reduces total sum differently.
        // We'll let fuzzer provide two actors and amounts.
    }
}

