pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 preBalance, uint256 otherDeposit) public {
        // preBalance: starting balance for the test actor (can be zero or positive)
        // otherDeposit: an unrelated deposit to ensure the contract holds enough Ether for cash-outs
        vm.assume(preBalance <= 1000 ether);
        vm.assume(otherDeposit >= 1 ether && otherDeposit <= 1000 ether);

        address actor = address(0x1234);
        address other = address(0x5678);

        // Give the actor some Ether to deposit, and pre-fund their balance if preBalance > 0
        vm.deal(actor, preBalance + 1 ether);
        if (preBalance > 0) {
            vm.prank(actor);
            c.Deposit{value: preBalance}();
        }

        // Make an unrelated deposit to ensure the contract has enough Ether for cash-outs
        vm.deal(other, otherDeposit);
        vm.prank(other);
        c.Deposit{value: otherDeposit}();

        // Actor deposits exactly MinDeposit (1 ether)
        vm.prank(actor);
        c.Deposit{value: 1 ether}();

        // Now actor attempts to cash out exactly MinDeposit (1 ether)
        // The reference contract should allow this (balance >= 1 ether after deposit),
        // the buggy contract should revert because the deposit was not recorded.
        bool success;
        vm.prank(actor);
        try c.CashOut(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // If actor had preBalance >= 1 ether, both versions would succeed, so we only
        // care about the case where preBalance < 1 ether, where the reference succeeds
        // and the buggy reverts. The property we assert: If preBalance < 1 ether,
        // the cash-out succeeds in the reference and fails in the buggy.
        // However, the fuzzer tests only one version at a time. We assert the property
        // that the reference contract ALWAYS succeeds for this scenario when preBalance < 1 ether.
        if (preBalance < 1 ether) {
            assertTrue(success);
        } else {
            // If preBalance >= 1 ether, both versions succeed, so we just assert true
            assertTrue(true);
        }
    }
}

