import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 cashOutAmt, address sender) public {
        vm.assume(sender != address(0) && sender != address(this) && sender != address(c));
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(cashOutAmt <= depositAmt);

        vm.deal(sender, depositAmt);
        vm.prank(sender);
        c.Deposit{value: depositAmt}();

        uint balBefore = c.balances(sender);
        uint contractBalBefore = address(c).balance;

        vm.prank(sender);
        c.CashOut(cashOutAmt);

        uint balAfter = c.balances(sender);
        uint contractBalAfter = address(c).balance;

        // Reference invariant: the sender's recorded balance plus the contract's ETH
        // must decrease by at most the cashOut amount (balance + contract ETH is non-increasing
        // because ETH leaves the system). More specifically, recorded balance decreases by exactly
        // cashOutAmt in the reference, but the mutant fails to record some deposits, so the
        // recorded balance may drop below zero or become inconsistent with actual ETH held.
        // We check: balAfter <= balBefore (no underflow or increase) and
        // (balBefore + contractBalBefore) - (balAfter + contractBalAfter) == cashOutAmt.
        // The mutant may violate this because it didn't add deposit to balances, so balBefore
        // may be 0 and balAfter may underflow or the invariant breaks.
        assertTrue(
            balAfter <= balBefore &&
            (balBefore + contractBalBefore) == (balAfter + contractBalAfter + cashOutAmt)
        );
    }
}

