        vm.assume(cashOutAmt <= withdrawerBal);

        vm.prank(withdrawer);
        c.CashOut(cashOutAmt);

        // Invariant: Sum of all tracked balances (depositor + withdrawer) == contract ETH balance + total cashOuts
        uint256 totalBalances = c.balances(depositor) + c.balances(withdrawer);
        uint256 contractBalance = address(c).balance;

        // In a correct system: deposited amount is in balances, withdrawn is subtracted.
        // Since no other activity, totalBalances should equal contractBalance.
        assertTrue(totalBalances == contractBalance);
    }
}

